syntaxExplanation.pattern:
for (int i = 0; i < 5; i++) {
  // Runs 5 times (i = 0, 1, 2, 3, 4)
}

codeExamples.code:
const int LED_PIN = 9;
void setup() { pinMode(LED_PIN, OUTPUT); }
void loop() {
  for (int b = 0; b <= 255; b += 5) {
    analogWrite(LED_PIN, b);
    delay(15);
  }
}

