  // Runs while condition stays true
}

codeExamples.code:
const int START_BTN = 2;
void setup() {
  pinMode(START_BTN, INPUT_PULLUP);
  Serial.begin(9600);
  Serial.println("Press button to start...");
  while (digitalRead(START_BTN) == HIGH) {
    delay(10);
  }
  Serial.println("Robot launched!");
}
void loop() {}

