syntaxExplanation.pattern:
do {
  // Runs at least once
} while (condition);

codeExamples.code:
void setup() {
  Serial.begin(9600);
  int reading;
  int tries = 0;
  do {
    reading = analogRead(A0);
    tries++;
  } while (reading == 0 && tries < 5);
  Serial.println(reading);
}
void loop() {}

