codeExamples.code:
const int LED_PIN = 13;
void setup() {
  pinMode(LED_PIN, OUTPUT);
  for (int burst = 0; burst < 3; burst++) {
    for (int pulse = 0; pulse < 3; pulse++) {
      digitalWrite(LED_PIN, HIGH); delay(150);
      digitalWrite(LED_PIN, LOW);  delay(150);
    }
    delay(600); // Pause between bursts
  }
}
void loop() {}

