codeExamples.code:
void setup() {
  Serial.begin(9600);
  int readings[5] = {120, -1, 340, 950, 200};
  for (int i = 0; i < 5; i++) {
    if (readings[i] < 0) continue;
    if (readings[i] > 900) {
      Serial.println("Limit hit - abort!");
      break;
    }
    Serial.println(readings[i]);
  }
}
void loop() {}

